from abc import ABCMeta
from six import add_metaclass, ensure_text
from time import sleep

from ..exceptions import UnsupportedOperation


@add_metaclass(ABCMeta)
class SignalAnalyzer(object):
    """ Base class for all types of signal analyzers """

    _UNSUPPORTED_OPERATION_MSG = "Device type '{}' doesn't support operation '{}'"

    def __init__(self):
        self._transport = None

    def set_mode(self, mode, timeout):
        """
        Sets given operating mode on the device.
        :param mode: one of available modes
        :type mode: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when unsupported mode is provided
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_mode.__name__))

    def get_mode(self, timeout):
        """
        Gets current operating mode from the device.
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current operating mode
        :rtype: str
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_mode.__name__))

    def set_center_frequency(self, frequency, unit, timeout):
        """
        Sets given center frequency on the device.
        :param frequency: value from allowed range
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when unsupported unit name is provided or frequency is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_center_frequency.__name__))

    def get_center_frequency(self, unit, timeout):
        """
        Gets current center frequency from the device.
        :param unit: name of unit in which returned frequency should be expressed, i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current center frequency
        :rtype: float
        :raises IncorrectOperation: when unsupported unit name is provided
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_center_frequency.__name__))

    def set_frequency_span(self, frequency, unit, timeout):
        """
        Sets given frequency span on the device.
        :param frequency: value from allowed range
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when unsupported unit name is provided or frequency is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_frequency_span.__name__))

    def get_frequency_span(self, unit, timeout):
        """
        Gets current frequency span from the device.
        :param unit: name of unit in which returned frequency should be expressed, i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current frequency span
        :rtype: float
        :raises IncorrectOperation: when unsupported unit name is provided
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_frequency_span.__name__))

    def set_bandwidth(self, frequency, unit, timeout):
        """
        Sets given bandwidth on the device.
        :param frequency: value from allowed range
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when unsupported unit name is provided or frequency is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_bandwidth.__name__))

    def get_bandwidth(self, unit, timeout):
        """
        Gets current bandwidth from the device.
        :param unit: name of unit in which returned frequency should be expressed, i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current bandwidth
        :rtype: float
        :raises IncorrectOperation: when unsupported unit name is provided
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_bandwidth.__name__))

    def set_resolution_bandwidth(self, frequency, unit, timeout):
        """
        Sets given resolution bandwidth on the device.
        :param frequency: value from allowed range
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when unsupported unit name is provided or frequency is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_resolution_bandwidth.__name__))

    def get_resolution_bandwidth(self, unit, timeout):
        """
        Gets current resolution bandwidth from the device.
        :param unit: name of unit in which returned frequency should be expressed, i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current resolution bandwidth
        :rtype: float
        :raises IncorrectOperation: when unsupported unit name is provided
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_resolution_bandwidth.__name__))

    def set_video_bandwidth(self, frequency, unit, timeout):
        """
        Sets given video bandwidth on the device.
        :param frequency: value from allowed range
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when device is not in appropriate mode, unsupported unit name is provided or
                                    frequency is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_video_bandwidth.__name__))

    def get_video_bandwidth(self, unit, timeout):
        """
        Gets current video bandwidth from the device.
        :param unit: name of unit in which returned frequency should be expressed, i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current video bandwidth
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode or unsupported unit name is provided
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_video_bandwidth.__name__))

    def set_sweep_acquisition(self, acquisition, timeout):
        """
        Sets given sweep acquisition on the device.
        :param acquisition: value from allowed range
        :type acquisition: int
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when device is not in appropriate mode or acquisition is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_sweep_acquisition.__name__))

    def get_sweep_acquisition(self, timeout):
        """
        Gets current sweep acquisition from the device.
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current sweep acquisition
        :rtype: int
        :raises IncorrectOperation: when device is not in appropriate mode
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_sweep_acquisition.__name__))

    def set_sweep_points(self, points, timeout):
        """
        Sets given sweep points count on the device.
        :param points: value from allowed range
        :type points: int
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when device is not in appropriate mode or points are out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_sweep_points.__name__))

    def get_sweep_points(self, timeout):
        """
        Gets current sweep points count from the device.
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current sweep points count
        :rtype: int
        :raises IncorrectOperation: when device is not in appropriate mode
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_sweep_points.__name__))

    def set_attenuation(self, power_level, timeout):
        """
        Sets given attenuation on the device.
        :param power_level: value from allowed range
        :type power_level: float
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when power level is not a number or is out of range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_attenuation.__name__))

    def get_attenuation(self, timeout):
        """
        Gets current attenuation from the device.
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current attenuation in dB
        :rtype: float
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_attenuation.__name__))

    def set_external_gain(self, power_level, timeout):
        """
        Sets given external gain on the device.
        :param power_level: value from allowed range
        :type power_level: float
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when power level is not a number or is out of range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_external_gain.__name__))

    def get_external_gain(self, timeout):
        """
        Gets current external gain from the device.
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current external gain in dB
        :rtype: float
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_external_gain.__name__))

    def set_channel_power_measurement(self, timeout):
        """
        Starts channel power measurement on the device.
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when device is not in appropriate mode
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(
            self.__class__.__name__, self.set_channel_power_measurement.__name__))

    def set_channel_integrating_bandwidth(self, frequency, unit, timeout):
        """
        Starts channel power measurement and sets channel integrating bandwidth on the device.
        :param frequency: value from allowed range
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when device is not in appropriate mode, unsupported unit name
                                    is provided or frequency is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(
            self.__class__.__name__, self.set_channel_integrating_bandwidth.__name__))

    def get_channel_integrating_bandwidth(self, unit, timeout):
        """
        Gets current channel integrating bandwidth from device.
        :param unit: name of unit in which returned frequency should be expressed, i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current channel integrating bandwidth
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode or unsupported unit name is provided
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(
            self.__class__.__name__, self.get_channel_integrating_bandwidth.__name__))

    def measure_channel_power(self, timeout):
        """
        Starts channel power measurement and gets current channel power measurement from the device.
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: device's current channel power measurement
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.measure_channel_power.__name__))

    def get_marker_y_axis(self, marker_id, timeout):
        """
        Gets Y axis value of given marker from the device.
        :param marker_id: ID of marker for which Y axis value should be read
        :type marker_id: int
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :return: Y axis value of given marker
        :rtype: float
        :raises IncorrectOperation: when marker ID is out of allowed range
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_marker_y_axis.__name__))

    def _execute_command(self, command, timeout, delay=0):
        """
        Executes given command on device and waits in idle (sleeps) given value of delay.
        :param command: command to be executed
        :type command: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :param delay: time to wait (sleep) after command is send; defaults to 0 seconds
        :type delay: float
        """
        self._transport.execute_command(self._to_unicode(command), timeout)
        sleep(delay)

    def _execute_query(self, query, timeout, delay=0):
        """
        Executes given query on device, waits in idle (sleeps) given value of delay and returns response.
        :param query: query to be executed
        :type query: str
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :param delay: time to wait (sleep) after query is send; defaults to 0 seconds
        :type delay: float
        :return: response to executed query
        :rtype: str
        """
        response = self._to_unicode(self._transport.execute_query(self._to_unicode(query), timeout))
        sleep(delay)
        return response

    @staticmethod
    def _to_unicode(byte_string):
        """
        Converts byte string into unicode string.
        :param byte_string: byte string to be converted
        :type byte_string: str
        :return: converted unicode string
        :rtype: str
        """
        return ensure_text(byte_string)
